'use strict';
function q(en,ar){return M.lang==='ar'?ar:en}
function workSeed(){return {seq:1,events:[],evaluation:{state:'draft',text:'',privateNote:'',reason:'',version:1,publications:[]},finance:{bill:null,receipt:null,unknown:false,adjustments:[]},pay:{contract:false,exception:true,state:'draft',reference:''},commerce:{state:'current',proof:'none'},messages:{state:'draft',text:'',audience:[],results:[]},media:{state:'empty',items:[],expired:false},support:{state:'open',replies:[],notes:[],customer:false},stock:{west:0,east:0,movements:[]},export:{state:'idle',done:0,rows:60},privacy:{state:'idle',hold:false,cleanup:false},incident:{state:'investigating',proposal:false,evidence:false},serviceTab:'inventory',service:'Database',collector:'fresh',identity:{state:'signed-out',roles:[],childMode:false},authority:{state:'pending',scope:'West Demo Branch'},changes:{state:'scheduled',version:1},preferences:{language:'en',channel:false},form:{},scenario:'normal'}}
function W(){return M.work||(M.work=workSeed())}
function sh(key){const names={studio:q('Complete design review','مراجعة التصميم الكامل'),sIdentity:q('Identity & context','الهوية والسياق'),sAuthority:q('Staff & authority','الموظفون والصلاحيات'),sChanges:q('Session changes','تغييرات الحصص'),sEvaluation:q('Evaluations','التقييمات'),sProgress:q('Published progress','التقدم المنشور'),sFinance:q('Family finance','مالية العائلة'),sPay:q('Trainer compensation','مستحقات المدرب'),sCommerce:q('Platform commerce','اشتراك الأكاديمية'),sMessages:q('Communications','الاتصالات'),sMedia:q('Private media','الوسائط الخاصة'),sSupport:q('Support cases','حالات الدعم'),sInventory:q('Inventory','المخزون'),sExport:q('Reports & exports','التقارير والتصدير'),sPrivacy:q('Privacy requests','طلبات الخصوصية'),sServices:q('Services & Operations','الخدمات والعمليات'),sIncident:q('Incident review','مراجعة الحادث'),sPreferences:q('Profile & preferences','الملف والتفضيلات')};Object.assign(names,{sPeopleLifecycle:q('Import & player lifecycle','الاستيراد وحياة اللاعب'),sOffline:q('Offline recovery concept','مفهوم التعافي غير المتصل'),sRelease:q('Release & native concepts','الإصدارات والمفاهيم الأصلية')});return names[key]||key}
function studioNav(){return Object.keys(studioRoutes).filter(k=>k!=='sProgress'&&k!=='sIncident').map(k=>[k,k==='studio'?'home':k==='sServices'?'shield':'file'])}
function sHead(page,ids,actions=''){return head(sh(page),q('Design review · fictional fixtures · no external actions','مراجعة تصميم · بيانات خيالية · دون إجراءات خارجية'),actions,ids)}
function sPolicy(ids,detail=''){return notice(q('Policy to confirm','سياسة تحتاج إلى تأكيد'),esc(ids+' · '+(detail||q('Every role, amount, limit and outcome is a review fixture until the named policy is accepted.','كل دور ومبلغ وحد ونتيجة مثال للمراجعة حتى اعتماد السياسة المحددة.'))),'warn')}
function sButtons(...args){return `<div class="section actions">${args.join('')}</div>`}
function sField(id,en,ar,value='',type='text'){return field(id,q(en,ar),value,type)}
function sValue(id){return document.getElementById(id)?.value.trim()||''}
function sCheck(id){return !!document.getElementById(id)?.checked}
function sConfirm(id){return `<label class="checkline"><input type="checkbox" id="${id}">${q('I reviewed this fictional scope and its consequences.','راجعت النطاق الخيالي ونتائجه.')}</label>`}
function sLog(action){const ref='SIM-FULL-'+W().seq++;W().events.unshift({ref,action,page:M.page});persist();return ref}
function sSaved(action){studioDrafts[M.page]={};M.error='';M.toast=q('Simulated receipt · ','إيصال تجريبي · ')+sLog(action);M.dirty=false;render()}
function sError(message){showError(message||t('required'))}
function sAudit(){return `<details class="section"><summary>${q('Operation history','سجل العمليات')}</summary><ol class="timeline">${W().events.slice(0,12).map(e=>`<li><b>${esc(e.action)}</b><p><bdi dir="ltr">${e.ref}</bdi> · ${esc(sh(e.page))}</p></li>`).join('')}</ol></details>`}
function studioHome(){return sHead('studio','Batches 3–5 · Connected review paths')+`<div class="form-panel">${sPolicy('D-001–022',q('No policy, native-language, accessibility, security or owner acceptance is inferred.','لا يُفترض اعتماد السياسات أو اللغة أو الإتاحة أو الأمان أو قبول المالك.'))}<div class="work-card"><h2>${q('Choose a connected journey','اختر رحلة مترابطة')}</h2><p class="subtitle">${q('Each domain has explicit review, outcome and recovery states. Use the domain controls to advance simulated background work.','لكل مجال حالات مراجعة ونتيجة وتعافٍ صريحة. استخدم أدوات المجال لتقديم العمل الخلفي التجريبي.')}</p>${Object.keys(studioRoutes).filter(k=>!['studio','sProgress','sIncident'].includes(k)).map(k=>`<button class="choice" data-action="nav:${k}"><span><b>${sh(k)}</b><small>${q('Local design path · review pending','مسار تصميم محلي · المراجعة معلّقة')}</small></span>${icon('arrow')}</button>`).join('')}</div></div>`}
function sStatePanel(){const state=W().scenario;if(state==='normal')return null;if(state==='restricted')return notice(q('Access changed','تغير الوصول'),q('This private projection is cleared. Choose an authorized context; no stale write is available.','أُخلي العرض الخاص. اختر سياقاً مصرحاً؛ لا يتاح تعديل بصلاحية قديمة.'),'error')+btn(q('Review contexts','مراجعة السياقات'),'s-context');if(state==='empty')return `<div class="empty"><h2>${q('No matching authorized records','لا توجد سجلات مصرح بها مطابقة')}</h2>${btn(t('clear'),'s-recover')}</div>`;if(state==='loading')return `<div class="work-card" aria-busy="true"><h2>${t('loading')}</h2><div class="skeleton"></div><div class="skeleton"></div>${btn(t('next'),'s-recover')}</div>`;return notice(q('Read unavailable','القراءة غير متاحة'),q('The result is unknown, not zero. Other regions remain available.','النتيجة غير معروفة ولا تعني صفراً. تبقى المناطق الأخرى متاحة.'),'error')+btn(t('retry'),'s-recover')}
function sScenarios(){return `<details class="section"><summary>${q('Domain review states','حالات مراجعة المجال')}</summary><div class="section actions">${['normal','loading','empty','failed','restricted'].map(x=>btn(q(x,{normal:'عادي',loading:'تحميل',empty:'فارغ',failed:'فشل',restricted:'مقيّد'}[x]),'s-state:'+x,'small')).join('')}</div></details>`}
function studioPage(){const state=sStatePanel();return (state?sHead(M.page,'State review')+state:studioRoutes[M.page]())+sScenarios()+sAudit()}
function studioAction(action){const [key,value]=action.split(':');if(key==='studio-start'){const enter=()=>{M.dirty=false;M.labActive=false;M.studioActive=true;M.page='studio';M.scenario='happy';W().scenario='normal';render(true)};M.dirty?ask(t('unsaved'),t('unsavedCopy'),enter):enter();return true}if(!key.startsWith('s-'))return false;if(key==='s-state'){W().scenario=value;render();return true}if(key==='s-recover'){W().scenario='normal';render();return true}if(key==='s-context'){W().scenario='normal';M.page='sIdentity';render(true);return true}return expandedAction(key,value)||identityAction(key,value)||commercialAction(key,value)||operationsAction(key,value)||servicesAction(key,value)}
function stateLabel(value){const ar={draft:'مسودة',submitted:'مقدّم',returned:'معاد للتعديل',approved:'معتمد',published:'منشور',current:'حالي',scheduled:'مجدول','effective fixture':'مثال سارٍ','restricted example · exact allowances policy pending':'مثال مقيّد · استثناءات السياسة معلّقة','recovery reviewed · no commercial activation':'رُوجع التعافي · لا تفعيل تجاري',none:'لا يوجد',staged:'مهيّأ','under review':'قيد المراجعة','accepted fixture':'مثال مقبول',rejected:'مرفوض','review-required':'يتطلب مراجعة','approved · amounts policy pending':'معتمد · سياسة المبالغ معلّقة','payout recorded as intent only · amount unconfirmed':'الصرف نية فقط · المبلغ غير مؤكد',reviewed:'مراجع',queued:'بالطابور',partial:'جزئي','partial · unresolved failed attempt':'جزئي · محاولة فاشلة غير محلولة',open:'مفتوح','waiting for customer · delivery pending':'بانتظار العميل · التسليم معلّق',escalated:'مصعّد','resolved · evidence fixture':'محلول · مثال دليل',idle:'لم يبدأ',processing:'قيد المعالجة',ready:'جاهز',failed:'فشل',expired:'منتهي الصلاحية','request recorded':'الطلب مسجل',held:'محجوز','authority reviewed fixture':'مثال سلطة مراجع','subsystem checklist prepared':'قائمة الأنظمة جاهزة','simulated case closed · no actual erasure':'أُغلقت الحالة التجريبية · لا محو فعلي',investigating:'قيد التحقيق','acknowledged · demo operator':'تم الإقرار · مشغل تجريبي','evidence recorded':'الدليل مسجل','controlled proposal awaiting real approval':'اقتراح مضبوط بانتظار موافقة فعلية','fictional recovery observed · independent verification pending':'تعافٍ خيالي ملاحظ · التحقق المستقل معلّق',fresh:'ملاحظة حديثة','unavailable · last observation stale; provider state unknown':'غير متاح · الملاحظة قديمة وحالة المزود مجهولة','fresh fixture · provider state still unknown':'مثال حديث · حالة المزود ما زالت مجهولة','signed-out':'غير مسجل الدخول','signed-in fixture · no actual authentication':'نموذج مسجل الدخول · لا مصادقة فعلية','identity-provider recovery guidance · no code collected':'إرشاد استعادة مزود الهوية · لا رمز مجمع','no membership':'لا عضوية','suspended · no private context':'موقوف · لا سياق خاص',pending:'معلّق','profile exists · invitation delivery pending':'الملف موجود · تسليم الدعوة معلّق','branch transfer fixture reviewed · history preserved':'رُوجع نقل الفرع التجريبي · التاريخ محفوظ','revoked fixture · new access denied':'مثال ملغى · الوصول الجديد ممنوع','ownership recovery case pending independent review':'استعادة الملكية بانتظار مراجعة مستقلة','preview ready':'المعاينة جاهزة','future cancellation fixture · historical records preserved':'إلغاء مستقبلي تجريبي · التاريخ محفوظ','reschedule proposal · date/conflict policy unresolved':'اقتراح جدولة · سياسة التاريخ والتعارض غير محسومة','substitution fixture · previous assignment retained in history':'استبدال تجريبي · التعيين السابق محفوظ'};return M.lang==='ar'?(ar[value]||value):value}
// Unsaved review input remains in memory across locale/theme changes, never in storage.
const studioDrafts={};
function restoreStudioDrafts(){if(!M.studioActive)return;for(const [id,value] of Object.entries(studioDrafts[M.page]||{})){const el=document.getElementById(id);if(!el)continue;if(el.type==='checkbox')el.checked=value;else el.value=value}}
document.addEventListener('input',e=>{if(!M.studioActive||!e.target.closest('.main')||!e.target.id)return;studioDrafts[M.page]||={};studioDrafts[M.page][e.target.id]=e.target.type==='checkbox'?e.target.checked:e.target.value;M.dirty=true});
